'use strict';
(()=>{
const fmt=n=>new Intl.NumberFormat('vi-VN').format(n)+'đ';
const pickers=document.querySelectorAll('.purchase');
let cart=[];try{const value=JSON.parse(localStorage.getItem('snh-estimate-v1')||'[]');if(Array.isArray(value))cart=value.filter(x=>x&&typeof x.key==='string'&&typeof x.name==='string'&&typeof x.variant==='string'&&Number.isFinite(x.price)&&x.price>0&&Number.isInteger(x.qty)&&x.qty>=1&&x.qty<=99);}catch{}
const catalog=JSON.parse(document.getElementById('catalog-data').textContent);
const priceNote=c=>c.assumed?'Giá giả định để duyệt':c.price_kind==='cost'?'Giá cốt · theo thông tin chủ hộ':'Giá bán công khai';
const previousCount=cart.length;
cart=cart.flatMap(x=>{const c=catalog[x.key];const v=c?.variants.find(v=>v.label===x.variant);return v?[{...x,name:names[x.key]||x.name,price:v.price,priceNote:priceNote(c)}]:[];});
if(previousCount!==cart.length)notify('Quy cách đã thay đổi. Vui lòng chọn lại những mẫu cũ không còn trong danh mục.');
function save(){try{localStorage.setItem('snh-estimate-v1',JSON.stringify(cart));}catch{notify('Không thể lưu lâu dài. Dự toán chỉ được giữ trong phiên hiện tại.');}}
function quantity(input){const n=Number(input.value);return Math.min(99,Math.max(1,Number.isFinite(n)?Math.round(n):1));}
function updateBadge(){document.querySelectorAll('.saved-count').forEach(x=>x.textContent=cart.reduce((n,x)=>n+x.qty,0));document.querySelector('.saved-link')?.setAttribute('aria-label','Xem danh sách dự toán');}
function drawCart(){updateBadge();const box=document.getElementById('cart-items');if(!box)return;box.replaceChildren();if(!cart.length){const p=document.createElement('p');p.textContent='Chưa có sản phẩm trong dự toán. Chọn quy cách tại trang sản phẩm để thêm.';box.append(p);}cart.forEach((item,index)=>{const row=document.createElement('div');row.className='estimate-row';const desc=document.createElement('div');const h=document.createElement('h3');h.textContent=item.name;const small=document.createElement('small');small.textContent=item.variant+' · '+fmt(item.price)+'/sản phẩm · '+item.priceNote;desc.append(h,small);const qty=document.createElement('input');qty.type='number';qty.min='1';qty.max='99';qty.value=item.qty;qty.setAttribute('aria-label','Số lượng '+item.name);qty.addEventListener('change',()=>{cart[index].qty=quantity(qty);save();drawCart();});const total=document.createElement('strong');total.textContent=fmt(item.price*item.qty);const del=document.createElement('button');del.textContent='Xóa';del.setAttribute('aria-label','Xóa '+item.name+' '+item.variant);del.addEventListener('click',()=>{cart.splice(index,1);save();drawCart();});row.append(desc,qty,total,del);box.append(row);});document.querySelector('.cart-total').textContent='Tổng dự kiến: '+fmt(cart.reduce((n,x)=>n+x.price*x.qty,0));const download=document.getElementById('download-cart');if(download)download.disabled=!cart.length;}
pickers.forEach(p=>{const select=p.querySelector('select'),input=p.querySelector('.quantity');function update(){const price=Number(select.selectedOptions[0].dataset.price);input.value=quantity(input);p.querySelector('.variant-price').textContent=fmt(price);p.querySelector('.line-total').textContent=fmt(price*Number(input.value));}select.addEventListener('change',update);input.addEventListener('change',update);p.querySelectorAll('[data-step]').forEach(b=>b.addEventListener('click',()=>{input.value=quantity(input)+Number(b.dataset.step);update();}));p.querySelector('.cart-add').addEventListener('click',()=>{update();const option=select.selectedOptions[0],variant=option.textContent.split(' — ')[0],price=Number(option.dataset.price),key=p.dataset.product;const old=cart.find(x=>x.key===key&&x.variant===variant);if(old)old.qty=Math.min(99,old.qty+Number(input.value));else cart.push({key,name:names[key]||key,variant,price,priceNote:priceNote(catalog[key]),qty:Number(input.value)});save();updateBadge();notify('Đã thêm vào dự toán. Xem tại trang Liên hệ.');p.querySelector('.cart-add').textContent='Đã thêm · Thêm tiếp ＋';});});
document.getElementById('download-cart')?.addEventListener('click',()=>{if(!cart.length)return;const lines=['SÂM NỮ HOÀNG — DỰ TOÁN BẢN DUYỆT','Hộ kinh doanh Đỗ Thị Tuyết | 0972 686 765','MỖI DÒNG GHI RÕ GIÁ BÁN CÔNG KHAI, GIÁ CỐT HOẶC GIÁ GIẢ ĐỊNH','',...cart.map(x=>`${x.name} | ${x.variant} | SL ${x.qty} | ${fmt(x.price)} | ${fmt(x.price*x.qty)} | ${x.priceNote}`),'','Tổng dự kiến: '+fmt(cart.reduce((n,x)=>n+x.price*x.qty,0)),'Chưa gửi đơn hàng. Vui lòng liên hệ xác nhận thông số và giá.'];const u=URL.createObjectURL(new Blob(['\uFEFF'+lines.join('\n')],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=u;a.download='du-toan-sam-nu-hoang.txt';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),1000);});
const search=document.getElementById('article-search');search?.addEventListener('input',()=>{const q=normalize(search.value);let count=0;document.querySelectorAll('.searchable-journal .journal-card').forEach(c=>{c.hidden=!normalize(c.textContent).includes(q);if(!c.hidden){count++;c.classList.add('in-view');}});document.getElementById('article-status').textContent=count+' bài phù hợp';document.getElementById('article-empty').hidden=count>0;});drawCart();
})();
